<?php if($canManage): ?><div class="card border-0 shadow-sm rounded-4 mb-4"><div class="card-body p-4"><h5 class="fw-bold">Attach evidence & provenance</h5><form method="post" enctype="multipart/form-data" action="<?= base_url('education/ksp/'.$version['uuid'].'/evidence') ?>" class="row g-3"><?= csrf_field() ?><div class="col-md-3"><label class="form-label">Target type</label><select class="form-select" name="target_type" required><?php foreach(KspEvidenceService::TARGETS as $type): ?><option><?= esc($type) ?></option><?php endforeach ?></select></div><div class="col-md-5"><label class="form-label">Target record</label><select class="form-select" name="target_uuid" required><?php foreach($targets as $target): ?><option value="<?= esc($target['uuid']) ?>"><?= esc($target['type'].' · '.$target['label']) ?></option><?php endforeach ?></select></div><div class="col-md-4"><label class="form-label">Evidence type</label><select class="form-select" name="evidence_type"><?php foreach($evidenceTypes as $type): ?><option><?= esc($type) ?></option><?php endforeach ?></select></div><div class="col-md-4"><label class="form-label">Source</label><input class="form-control" name="source" required></div><div class="col-md-3"><label class="form-label">Date</label><input class="form-control" type="date" name="date" required></div><div class="col-md-5"><label class="form-label">File (optional, max 10 MB)</label><input class="form-control" type="file" name="evidence_file"></div><div class="col-md-5"><label class="form-label">Reference (required if no file)</label><input class="form-control" name="reference"></div><div class="col-md-7"><label class="form-label">Description</label><input class="form-control" name="description" required></div><div class="col-12"><button class="btn btn-primary">Simpan evidence</button></div></form></div></div><?php endif ?>
<div class="card border-0 shadow-sm rounded-4"><div class="card-body p-4"><h5 class="fw-bold">Evidence Index</h5><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Type</th><th>Target</th><th>Source & date</th><th>Description</th><th>Reference/hash</th></tr></thead><tbody><?php foreach($rows as $row): ?><tr><td><?= esc($row['evidence_type']) ?></td><td><?= esc($row['target_type']) ?></td><td><?= esc($row['source_name']) ?><br><small><?= esc($row['evidence_date']) ?> · <?= esc($row['creator_name']??'System') ?></small></td><td><?= esc($row['description']) ?></td><td><?php if($row['storage_reference']): ?><a href="<?= base_url('education/ksp/'.$version['uuid'].'/evidence/'.$row['uuid'].'/download') ?>">Unduh file</a><br><small class="font-monospace"><?= esc($row['file_hash']) ?></small><?php else: ?><span><?= esc($row['reference_uri']) ?></span><?php endif ?></td></tr><?php endforeach ?><?php if(!$rows): ?><tr><td colspan="5" class="text-center text-muted py-5">Belum ada evidence.</td></tr><?php endif ?></tbody></table></div></div></div>
